function lang() { return window.location.pathname.indexOf('/en/') >= 0 ? 'en' : 'zh'; }
function t(key, params) {
  const d = DICT[lang()] || DICT.zh;
  let s = d[key] !== undefined ? d[key] : (DICT.zh[key] !== undefined ? DICT.zh[key] : key);
  if (params) Object.keys(params).forEach(k => { s = s.replace(new RegExp('\\{' + k + '\\}', 'g'), params[k]); });
  return s;
}
